-- ============================================================================
-- V425 : Nouveaux exemples-modèles EO réalistes
-- Générés à partir de la structure V424, avec contenus différents.
-- Amélioration : Tâche 1 plus développée dès la première réponse du candidat.
-- ============================================================================

DO $$
DECLARE
eo_t1 UUID;
eo_t2 UUID;
eo_t3 UUID;
BEGIN
SELECT id INTO eo_t1 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 1 AND niveau_cible = 'B1' LIMIT 1;
SELECT id INTO eo_t2 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 2 AND niveau_cible = 'B1' LIMIT 1;
SELECT id INTO eo_t3 FROM production_tasks
WHERE epreuve = 'TCF_EO' AND tache_numero = 3 AND niveau_cible = 'B1' LIMIT 1;

-- ========================================================================
-- EO TÂCHE 1
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
    eo_t1,
    E'Entretien dirigé : une assistante administrative se présente',
    E'Un échange réaliste : présentation personnelle plus longue, parcours, famille, quotidien, loisirs et projets.',
    E'[Examinateur] Bonjour. Pour commencer, pouvez-vous vous présenter de façon assez complète, s''il vous plaît ?\n[Candidat] Bonjour. Oui, bien sûr. Je m''appelle Aïcha Benali, j''ai 38 ans et je suis marocaine. Je suis née à Rabat, dans une famille assez nombreuse, avec deux frères et une sœur. Aujourd''hui, j''habite à Rennes, en Bretagne, avec mon mari et nos deux enfants. Mon fils a neuf ans et ma fille a six ans. Je vis en France depuis presque sept ans, et petit à petit, j''ai construit ici ma vie personnelle et professionnelle.\n[Examinateur] Très bien. Pouvez-vous parler un peu plus de votre parcours ?\n[Candidat] Au Maroc, j''ai étudié la comptabilité et j''ai travaillé pendant plusieurs années dans une petite entreprise familiale. Quand je suis arrivée en France, au début, ce n''était pas facile, parce que je ne connaissais pas bien les démarches administratives et je devais aussi améliorer mon français. J''ai suivi des cours, puis j''ai fait une formation courte d''assistante administrative. Aujourd''hui, je travaille dans une association qui accompagne des personnes âgées. Je m''occupe de l''accueil, des rendez-vous et parfois des dossiers. J''aime beaucoup ce travail, parce que je me sens utile.\n[Examinateur] Et comment se passe votre vie quotidienne ?\n[Candidat] Ma vie quotidienne est bien organisée. Le matin, je prépare les enfants pour l''école, ensuite je vais au travail en bus. Je travaille généralement de neuf heures à dix-sept heures. Le soir, je récupère les enfants, je prépare le dîner et j''aide mon fils à faire ses devoirs. Le week-end, nous aimons sortir au parc, voir des amis ou visiter les environs. Rennes est une ville agréable, pas trop grande, et je trouve les gens assez accueillants.\n[Examinateur] Qu''aimez-vous faire pendant votre temps libre ?\n[Candidat] Quand j''ai un peu de temps pour moi, j''aime marcher, lire des romans simples en français et cuisiner. La cuisine est très importante pour moi, parce qu''elle me permet de garder un lien avec mon pays. Par exemple, je prépare souvent du couscous ou des tajines quand nous invitons des amis. J''aime aussi découvrir des plats français, comme les crêpes ou les gratins.\n[Examinateur] Et quels sont vos projets pour l''avenir ?\n[Candidat] Mon premier projet, c''est de continuer à progresser en français, surtout à l''oral, pour être plus à l''aise dans mon travail. Ensuite, j''aimerais obtenir un poste plus stable dans l''administration ou dans une mairie, parce que j''aime le contact avec le public. Enfin, je souhaite demander la nationalité française. Mes enfants grandissent ici, mon mari travaille ici, et moi aussi je me sens de plus en plus chez moi en France. C''est pour cela que je prépare sérieusement le TCF.\n[Examinateur] Merci, votre présentation était complète.\n[Candidat] Merci beaucoup.',
    E'Ce modèle développe davantage la première réponse de la tâche 1 : identité, origine, famille, ville actuelle, durée de vie en France. C''est mieux qu''une présentation trop courte. Le candidat parle ensuite de son parcours, de son travail, de sa vie quotidienne, de ses loisirs et de ses projets. Le style reste naturel, avec des phrases simples mais complètes.',
    E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Bonjour. Pour commencer, pouvez-vous vous présenter de façon assez complète, s''il vous plaît ?</prosody><break time="700ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour. Oui, bien sûr. Je m''appelle Aïcha Benali, j''ai 38 ans et je suis marocaine. Je suis née à Rabat, dans une famille assez nombreuse, avec deux frères et une sœur. Aujourd''hui, j''habite à Rennes, en Bretagne, avec mon mari et nos deux enfants. Mon fils a neuf ans et ma fille a six ans. Je vis en France depuis presque sept ans, et petit à petit, j''ai construit ici ma vie personnelle et professionnelle.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Très bien. Pouvez-vous parler un peu plus de votre parcours ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Au Maroc, j''ai étudié la comptabilité et j''ai travaillé pendant plusieurs années dans une petite entreprise familiale. Quand je suis arrivée en France, au début, ce n''était pas facile, parce que je ne connaissais pas bien les démarches administratives et je devais aussi améliorer mon français. J''ai suivi des cours, puis j''ai fait une formation courte d''assistante administrative. Aujourd''hui, je travaille dans une association qui accompagne des personnes âgées. Je m''occupe de l''accueil, des rendez-vous et parfois des dossiers. J''aime beaucoup ce travail, parce que je me sens utile.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et comment se passe votre vie quotidienne ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Ma vie quotidienne est bien organisée. Le matin, je prépare les enfants pour l''école, ensuite je vais au travail en bus. Je travaille généralement de neuf heures à dix-sept heures. Le soir, je récupère les enfants, je prépare le dîner et j''aide mon fils à faire ses devoirs. Le week-end, nous aimons sortir au parc, voir des amis ou visiter les environs. Rennes est une ville agréable, pas trop grande, et je trouve les gens assez accueillants.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Qu''aimez-vous faire pendant votre temps libre ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Quand j''ai un peu de temps pour moi, j''aime marcher, lire des romans simples en français et cuisiner. La cuisine est très importante pour moi, parce qu''elle me permet de garder un lien avec mon pays. Par exemple, je prépare souvent du couscous ou des tajines quand nous invitons des amis. J''aime aussi découvrir des plats français, comme les crêpes ou les gratins.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Et quels sont vos projets pour l''avenir ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Mon premier projet, c''est de continuer à progresser en français, surtout à l''oral, pour être plus à l''aise dans mon travail. Ensuite, j''aimerais obtenir un poste plus stable dans l''administration ou dans une mairie, parce que j''aime le contact avec le public. Enfin, je souhaite demander la nationalité française. Mes enfants grandissent ici, mon mari travaille ici, et moi aussi je me sens de plus en plus chez moi en France. C''est pour cela que je prépare sérieusement le TCF.</prosody><break time="700ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Merci, votre présentation était complète.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci beaucoup.</prosody></voice></speak>',
    '["Présentation longue : identité, origine, famille, ville", "Parcours dans le pays d''origine", "Arrivée en France + difficultés", "Formation et travail actuel", "Vie quotidienne", "Loisirs", "Projets + lien avec le TCF"]'::jsonb,
    'B1', 1
);

-- ========================================================================
-- EO TÂCHE 2
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
    eo_t2,
    E'Jeu de rôle : s''inscrire à des cours de français',
    E'Le candidat appelle une association pour demander des informations et organiser un essai.',
    E'[Agent] Maison des associations, bonjour.\n[Candidat] Bonjour Madame. Je vous appelle parce que j''ai vu une affiche pour des cours de français du soir. Je voudrais avoir quelques renseignements, s''il vous plaît.\n[Agent] Bien sûr. Nous proposons plusieurs cours selon le niveau. Vous cherchez plutôt un cours débutant ou un cours intermédiaire ?\n[Candidat] Je pense que j''ai déjà un niveau intermédiaire. Je comprends assez bien, mais je veux améliorer mon oral et préparer un examen de français.\n[Agent] Dans ce cas, le groupe du mardi et du jeudi soir pourrait vous convenir. Les cours ont lieu de dix-huit heures trente à vingt heures.\n[Candidat] D''accord. Est-ce que les cours sont toute l''année ou seulement pendant quelques semaines ?\n[Agent] La session dure trois mois. Ensuite, les personnes peuvent se réinscrire si elles veulent continuer.\n[Candidat] Très bien. Et combien coûte l''inscription pour les trois mois ?\n[Agent] C''est trente euros pour l''année d''adhésion à l''association, puis quinze euros par mois pour les cours.\n[Candidat] D''accord, ce n''est pas trop cher. Est-ce qu''il faut apporter des documents pour s''inscrire ?\n[Agent] Oui, il faut une pièce d''identité, une photo et un justificatif de domicile.\n[Candidat] Très bien, j''ai tout ça. Est-ce que je peux venir essayer un cours avant de m''inscrire définitivement ?\n[Agent] Oui, c''est possible. Vous pouvez venir mardi prochain pour faire un essai gratuit.\n[Candidat] Parfait. Et l''adresse exacte, c''est bien près de la mairie ?\n[Agent] Oui, nous sommes au 8 rue Victor Hugo, juste derrière la mairie. L''entrée se fait par la petite porte bleue.\n[Candidat] Merci. Une dernière question : est-ce que le professeur donne aussi des conseils pour le TCF ?\n[Agent] Oui, pas à chaque cours, mais il y a souvent des exercices d''oral et de compréhension. Le professeur peut aussi vous orienter vers des ressources utiles.\n[Candidat] Très bien, c''est exactement ce que je cherche. Je viendrai mardi prochain à dix-huit heures trente avec mes documents.\n[Agent] Parfait, je note votre venue. Quel est votre nom ?\n[Candidat] Je m''appelle Karim El Mansouri.\n[Agent] Très bien Monsieur El Mansouri. À mardi.\n[Candidat] Merci beaucoup, bonne journée.\n[Agent] Bonne journée à vous.',
    E'Ce modèle montre une bonne tâche 2 : le candidat mène l''échange, pose plusieurs questions utiles et vérifie les informations importantes. Il ne se contente pas de répondre ; il obtient le prix, les horaires, les documents, l''adresse et la possibilité d''un essai.',
    E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-DeniseNeural"><prosody rate="0.95">Maison des associations, bonjour.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Bonjour Madame. Je vous appelle parce que j''ai vu une affiche pour des cours de français du soir. Je voudrais avoir quelques renseignements, s''il vous plaît.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bien sûr. Nous proposons plusieurs cours selon le niveau. Vous cherchez plutôt un cours débutant ou un cours intermédiaire ?</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je pense que j''ai déjà un niveau intermédiaire. Je comprends assez bien, mais je veux améliorer mon oral et préparer un examen de français.</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Dans ce cas, le groupe du mardi et du jeudi soir pourrait vous convenir. Les cours ont lieu de dix-huit heures trente à vingt heures.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord. Est-ce que les cours sont toute l''année ou seulement pendant quelques semaines ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">La session dure trois mois. Ensuite, les personnes peuvent se réinscrire si elles veulent continuer.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien. Et combien coûte l''inscription pour les trois mois ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">C''est trente euros pour l''année d''adhésion à l''association, puis quinze euros par mois pour les cours.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">D''accord, ce n''est pas trop cher. Est-ce qu''il faut apporter des documents pour s''inscrire ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, il faut une pièce d''identité, une photo et un justificatif de domicile.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, j''ai tout ça. Est-ce que je peux venir essayer un cours avant de m''inscrire définitivement ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, c''est possible. Vous pouvez venir mardi prochain pour faire un essai gratuit.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Parfait. Et l''adresse exacte, c''est bien près de la mairie ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, nous sommes au 8 rue Victor Hugo, juste derrière la mairie. L''entrée se fait par la petite porte bleue.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci. Une dernière question : est-ce que le professeur donne aussi des conseils pour le TCF ?</prosody><break time="600ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Oui, pas à chaque cours, mais il y a souvent des exercices d''oral et de compréhension. Le professeur peut aussi vous orienter vers des ressources utiles.</prosody><break time="600ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Très bien, c''est exactement ce que je cherche. Je viendrai mardi prochain à dix-huit heures trente avec mes documents.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Parfait, je note votre venue. Quel est votre nom ?</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Je m''appelle Karim El Mansouri.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Très bien Monsieur El Mansouri. À mardi.</prosody><break time="500ms"/></voice><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Merci beaucoup, bonne journée.</prosody><break time="500ms"/></voice><voice name="fr-FR-DeniseNeural"><prosody rate="1.0">Bonne journée à vous.</prosody></voice></speak>',
    '["Ouverture polie", "Objet de l''appel", "Niveau et besoin", "Horaires", "Durée et prix", "Documents", "Essai gratuit", "Adresse", "Confirmation finale"]'::jsonb,
    'B1', 1
);

-- ========================================================================
-- EO TÂCHE 3
-- ========================================================================
INSERT INTO production_examples (
    task_id, titre, resume, contenu, explications, ssml_text, plan_points, niveau_indicatif, display_order
) VALUES (
    eo_t3,
    E'Donner son opinion : le télétravail',
    E'Un monologue argumenté sur les avantages, les limites et l''équilibre nécessaire du télétravail.',
    E'[Candidat] Aujourd''hui, je vais parler du télétravail. Depuis quelques années, beaucoup de personnes travaillent parfois depuis leur domicile. À mon avis, le télétravail est une bonne chose, mais seulement s''il est bien organisé.\n\nD''abord, le premier avantage, c''est le gain de temps. Quand on travaille à la maison, on évite les transports, les embouteillages et la fatigue du trajet. Par exemple, une personne qui passe une heure le matin et une heure le soir dans les transports gagne deux heures dans sa journée. Elle peut utiliser ce temps pour sa famille, pour faire du sport ou simplement pour se reposer.\n\nEnsuite, le télétravail peut aider à mieux se concentrer. Dans certains bureaux, il y a beaucoup de bruit, des réunions, des collègues qui parlent ou qui interrompent. À la maison, si on a un endroit calme, on peut parfois travailler plus efficacement. Pour certains métiers administratifs ou informatiques, c''est vraiment pratique.\n\nMais il y a aussi des inconvénients. Le premier, c''est l''isolement. Quand on reste toujours chez soi, on voit moins ses collègues et on peut se sentir seul. Le deuxième problème, c''est la séparation entre la vie professionnelle et la vie personnelle. Certaines personnes continuent à répondre aux messages le soir ou pendant le week-end, parce que leur ordinateur est toujours à côté d''elles.\n\nJe pense donc que la meilleure solution, c''est un équilibre. Par exemple, deux jours de télétravail par semaine et trois jours au bureau. Comme ça, on garde le contact avec l''équipe, mais on profite aussi des avantages du travail à distance. L''entreprise doit aussi fixer des règles claires : horaires, droit à la déconnexion, réunions nécessaires seulement.\n\nPour conclure, je suis plutôt favorable au télétravail, mais pas à cent pour cent. Il peut améliorer la qualité de vie des salariés, à condition de respecter un cadre clair et de ne pas couper les personnes de leurs collègues.',
    E'Ce modèle convient à la tâche 3 : avis clair, deux arguments, limites, solution équilibrée et conclusion. Le style reste accessible, sans dissertation trop scolaire, mais avec des connecteurs utiles : d''abord, ensuite, mais, donc, pour conclure.',
    E'<speak version="1.0" xml:lang="fr-FR"><voice name="fr-FR-HenriNeural"><prosody rate="1.0">Aujourd''hui, je vais parler du télétravail. Depuis quelques années, beaucoup de personnes travaillent parfois depuis leur domicile. À mon avis, le télétravail est une bonne chose, mais seulement s''il est bien organisé.<break time="600ms"/>D''abord, le premier avantage, c''est le gain de temps. Quand on travaille à la maison, on évite les transports, les embouteillages et la fatigue du trajet. Par exemple, une personne qui passe une heure le matin et une heure le soir dans les transports gagne deux heures dans sa journée. Elle peut utiliser ce temps pour sa famille, pour faire du sport ou simplement pour se reposer.<break time="600ms"/>Ensuite, le télétravail peut aider à mieux se concentrer. Dans certains bureaux, il y a beaucoup de bruit, des réunions, des collègues qui parlent ou qui interrompent. À la maison, si on a un endroit calme, on peut parfois travailler plus efficacement. Pour certains métiers administratifs ou informatiques, c''est vraiment pratique.<break time="600ms"/>Mais il y a aussi des inconvénients. Le premier, c''est l''isolement. Quand on reste toujours chez soi, on voit moins ses collègues et on peut se sentir seul. Le deuxième problème, c''est la séparation entre la vie professionnelle et la vie personnelle. Certaines personnes continuent à répondre aux messages le soir ou pendant le week-end, parce que leur ordinateur est toujours à côté d''elles.<break time="600ms"/>Je pense donc que la meilleure solution, c''est un équilibre. Par exemple, deux jours de télétravail par semaine et trois jours au bureau. Comme ça, on garde le contact avec l''équipe, mais on profite aussi des avantages du travail à distance. L''entreprise doit aussi fixer des règles claires : horaires, droit à la déconnexion, réunions nécessaires seulement.<break time="600ms"/>Pour conclure, je suis plutôt favorable au télétravail, mais pas à cent pour cent. Il peut améliorer la qualité de vie des salariés, à condition de respecter un cadre clair et de ne pas couper les personnes de leurs collègues.</prosody></voice></speak>',
    '["Introduction + position", "Argument 1 : gain de temps", "Argument 2 : concentration", "Limites : isolement et frontière vie privée", "Solution équilibrée", "Conclusion nuancée"]'::jsonb,
    'B1', 1
);

END $$;
